get_site_settings.code:
var response = await client.SiteSettings.GetSiteSettingsAsync();
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var siteSettings = (IReadOnlyDictionary<string, object?>)body["site_settings"]!;
var storeDetails = (IReadOnlyDictionary<string, object?>)siteSettings["store_details"]!;
Console.WriteLine($"{storeDetails["company_name"]} {storeDetails["email"]}");

patch_site_settings.code:
var response = await client.SiteSettings.PatchSiteSettingsAsync(new Dictionary<string, object?>
{
    ["site_settings"] = new Dictionary<string, object?>
    {
        ["brand_kit"] = new Dictionary<string, object?> { ["palette_name"] = "Autumn" },
        ["date_time"] = new Dictionary<string, object?> { ["hide_time_zone"] = false },
    },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var siteSettings = (IReadOnlyDictionary<string, object?>)body["site_settings"]!;
var brandKit = (IReadOnlyDictionary<string, object?>)siteSettings["brand_kit"]!;
Console.WriteLine(brandKit["palette_name"]);

